#include "tests/support/socket/node_parse_test_fixture.hpp"
using namespace node_parse_test;
namespace {
void entry_depth_and_scratch(){
    for(std::uint32_t depth:{0U,98U,99U,100U,0xffffffffU}){Fixture f;f.raw.set(Memory::doc+0xa4,depth,4);f.raw.set(Memory::doc+0x6c,5,4);check(f.parse()==0,"initial existing error returns zero");f.check_depth(depth);check(f.lower.errors.size()==(depth==99?1U:0U)&&f.lower.identifies.empty(),"depth guard tests equality100 only,including32bit wrap");if(depth==99){const auto e=f.lower.errors[0];check(e.document==Memory::doc&&e.code==18&&e.line==7&&e.format==0x180080098&&!e.has_pointer&&!e.pointer,"depth guard exact error18 arguments");}}
    {Fixture f;check(f.parse(0)==0&&f.lower.identifies.empty(),"null cursor returns before byte lookup");f.check_depth();}
    {Fixture f;f.raw.input[0]=0;check(f.parse()==0&&f.lower.identifies.empty(),"NUL cursor returns without Identify");f.check_depth();}
    {Fixture f;f.raw.set(Memory::doc+0xa4,99,4);f.raw.set(Memory::other_doc+0xa4,88,4);f.lower.error_hook=[&](const auto&){f.raw.set(Memory::owner+8,Memory::other_doc);f.raw.set(Memory::doc+0xa4,41,4);};f.lower.identify_hook=[&](const auto& a){check(a.document==Memory::other_doc,"Identify sees live replacement document after depth error");return Memory::input_address+9;};check(f.parse()==0&&f.lower.identifies.size()==1&&f.lower.parses.empty(),"Identify null output returns0 despite nonnull returned cursor");f.check_depth(40);check(f.raw.get(Memory::other_doc+0xa4,4)==88,"epilog does not decrement replacement document");}
    {Fixture f;f.lower.parse_hook=[&](const auto& p){check(p.target==Memory::parse80&&p.node==Memory::child&&p.cursor==Memory::input_address+3&&p.pair==Memory::pair&&p.line==Memory::line,"Identify cursor and fourth line-pointer forwarded separately");check(f.raw.get(Memory::scratch_address)==((Memory::child&0xffffffff00000000ULL)|27)&&f.raw.get(Memory::pair,4)==0&&!f.raw.get(Memory::pair+8)&&!f.raw.get(Memory::pair+16),"out-node lowDWORD overwritten by child line; pair initialized fieldwise");check(f.raw.get(Memory::pair+4,4)==0xa5a5a5a5,"local pair padding untouched");return Memory::input_address+1;};check(f.parse()==0&&f.lower.preparations.size()==1,"ordinary EOF returns0 after source append");check(f.raw.get(Memory::owner+0x38)==Memory::child&&f.raw.get(Memory::owner+0x40)==Memory::child&&!f.raw.get(Memory::child+0x48)&&!f.raw.get(Memory::child+0x50)&&f.raw.get(Memory::child+0x10)==Memory::owner,"empty list append stores parent and sibling links");f.check_depth();}
}
void append_backedge_and_failed_parse(){
    {Fixture f;f.lower.prepare_hook=[&](auto o,auto){f.raw.set(o+0x40,Memory::last);};check(f.parse()==0&&f.raw.get(Memory::last+0x50)==Memory::child&&f.raw.get(Memory::child+0x48)==Memory::last,"prepare callback precedes live last-pointer lookup");}
    {Fixture f;f.raw.set(Memory::owner+0x40,Memory::owner-0x10);check(f.parse()==0&&f.raw.get(Memory::child+0x48)==Memory::child&&f.raw.get(Memory::owner+0x40)==Memory::child,"append rereads owner.last after aliased last.next store");}
    {Fixture f;f.raw.set(Memory::child+8,Memory::other_doc);check(f.parse()==0&&f.lower.preparations.empty()&&!f.raw.get(Memory::owner+0x38),"foreign document child skips append");}
    {Fixture f;f.raw.input[1]='y';unsigned calls=0;f.lower.identify_hook=[&](const auto& a){++calls;if(calls==1)f.raw.set(a.out,Memory::child);return a.cursor+1;};f.lower.prepare_hook=[&](auto,auto){f.raw.set(Memory::doc+0x6c,99,4);};check(f.parse()==0&&calls==2&&f.raw.get(Memory::doc+0x6c,4)==99,"backedge checks byte but does not recheck document error");}
    for(bool existing:{false,true}){Fixture f;f.lower.parse_hook=[&](const auto& p){f.raw.set(p.pair,0x200,4);f.raw.set(p.pair+8,0xfa00);return 0;};f.nodes.destroy_hook=[&](const auto&){if(existing)f.raw.set(Memory::doc+0x6c,71,4);};check(f.parse()==0,"failed child parse returns0");f.check_destroy();check(f.lower.errors.size()==(existing?0U:1U)&&f.lower.frees==std::vector<std::uintptr_t>{0xfa00},"failed parse only reports15 for live clear error,then frees local closing");if(!existing){const auto e=f.lower.errors[0];check(e.code==15&&e.line==27&&!e.format&&!e.has_pointer,"failed parse cached line and no variadic pointer");}f.check_depth();}
    {Fixture f;f.lower.parse_hook=[](const auto&){return 0;};f.nodes.destroy_hook=[&](const auto&){f.raw.set(Memory::child+0x60,Memory::other_pool);f.raw.set(Memory::pool,Memory::other_pool_table);f.raw.set(Memory::owner+8,Memory::other_doc);};check(f.parse()==0&&f.nodes.releases[0].pool==Memory::pool&&f.nodes.releases[0].target==Memory::other_release18&&f.lower.errors[0].document==Memory::other_doc,"cleanup caches pool before destructor but reads its release vtable and owner document afterward");}
}
void declarations(){
    for(unsigned scenario=0;scenario<5;++scenario){Fixture f;f.raw.set(Memory::owner+0x38,scenario>=2?Memory::first:0);f.raw.set(Memory::owner+0x40,scenario>=3?Memory::last:0);
        f.nodes.probe_hook=[&](auto t,auto n)->std::uint64_t{if(t==Memory::probe48){if(n==Memory::child)return Memory::declaration;if(n==Memory::first)return scenario==2?0:1;if(n==Memory::last)return scenario==3?0:1;}if(t==Memory::probe38)return n==Memory::owner?(scenario==0?0:1):1;return 0;};
        f.lower.name_hook=[&](auto p){check(p==Memory::declaration+0x18,"error11 names returned declaration object,not necessarily child");f.raw.set(Memory::owner+8,Memory::other_doc);return 0xfd11;};
        const bool legal=scenario==1||scenario==4;check(f.parse()==0&&f.lower.errors.size()==(legal?0U:1U),"declaration placement short-circuit matrix");if(!legal){const auto e=f.lower.errors[0];check(e.document==Memory::doc&&e.code==11&&e.line==27&&e.format==0x180080000&&e.has_pointer&&e.pointer==0xfd11,"declaration error uses document cached before name callback and explicit pointer argument");f.check_destroy();}
        if(scenario==0)check(f.nodes.probes.size()>=4&&f.nodes.probes[0].node==Memory::child&&f.nodes.probes[1].node==Memory::owner&&f.nodes.probes[2].node==Memory::declaration,"invalid owner short-circuits first/last declaration probes");
        if(scenario==1)check(std::none_of(f.nodes.probes.begin(),f.nodes.probes.end(),[](const auto& p){return p.node==Memory::last;}),"empty first list accepts without reading/probing last");f.check_depth();
    }
}
void matching_and_mismatching_elements(){
    for(unsigned mode:{0U,1U,3U})for(bool nonempty:{false,true}){Fixture f;f.element(mode,nonempty);const bool bad=(!nonempty&&mode==0)||(nonempty&&mode!=0);check(f.parse()==0&&f.lower.errors.size()==(bad?1U:0U),"element mode/closing-pair equality matrix");if(bad){const auto e=f.lower.errors[0];check(e.code==14&&e.line==27&&e.has_pointer&&e.pointer==0xf777&&e.format==0x180080018,"element mismatch exact typed error14 pointer transport");f.check_destroy();}else check(f.lower.preparations.size()==1,"accepted element appended");if(mode==0&&nonempty)check(f.lower.names.size()==2&&f.lower.comparisons.empty(),"same materialized pointer bypasses comparison");f.check_depth();}
    {Fixture f;f.element();f.lower.name_hook=[](auto p){return p==Memory::pair?0xf001:0xf002;};f.lower.compare_hook=[&](const auto& c){check(c.left==0xf001&&c.right==0xf002&&c.limit==0x7fffffff,"comparison preserves operand order and literal limit");f.raw.set(Memory::scratch_address,83,4);return 1;};check(f.parse()==0&&f.lower.errors[0].line==83&&f.lower.names.size()==3,"compare failure reloads scratch lowDWORD line before later diagnostic name lookup");}
    {Fixture f;f.element(1,true);f.lower.parse_hook=[&](const auto& p){f.raw.set(p.pair+8,1);f.raw.set(p.pair+16,2);f.raw.set(Memory::scratch_address,83,4);return Memory::input_address+1;};f.lower.name_hook=[&](auto){f.raw.set(Memory::owner+8,Memory::other_doc);return 0xf444;};check(f.parse()==0&&f.lower.errors[0].line==27&&f.lower.errors[0].document==Memory::doc,"direct mode mismatch retains cached line and captures document before materialization");}
    {Fixture f;f.element();f.nodes.probe_hook=[](auto t,auto n)->std::uint64_t{if(t==Memory::probe08&&n==Memory::child)return Memory::element;if(t==Memory::probe30)return 1;return t==Memory::probe38?1:0;};f.lower.name_hook=[](auto){return 0;};check(f.parse()==0&&f.lower.names==std::vector<std::uintptr_t>{Memory::pair}&&f.lower.comparisons.empty()&&f.lower.errors.empty(),"probe30 nonzero yields null element name and identity bypass remains exact");}
}
void closing_move_and_cleanup(){
    for(auto destination:{std::uintptr_t{0},Memory::element+0x18,Memory::output}){Fixture f;f.element(2);f.raw.set(Memory::element+0x18,0x201,4);f.raw.set(Memory::element+0x1c,0x76543210,4);f.raw.set(Memory::element+0x20,0xf101);f.raw.set(Memory::element+0x28,0xf109);f.raw.set(Memory::output,0x200,4);f.raw.set(Memory::output+4,0x12345678,4);f.raw.set(Memory::output+8,0xf999);
        check(f.parse(Memory::input_address,destination)==Memory::input_address+1,"mode2 returns child cursor and does not append");check(f.lower.preparations.empty()&&f.nodes.tracks.size()==1&&f.nodes.tracks[0].target==Memory::track20&&f.nodes.tracks[0].pool==Memory::pool,"mode2 tracks pool before cleanup");f.check_destroy();if(destination==Memory::output){check(f.lower.frees==std::vector<std::uintptr_t>{0xf999}&&f.raw.get(destination,4)==0x201&&f.raw.get(destination+8)==0xf101&&f.raw.get(destination+16)==0xf109,"distinct output releases old ownership then moves fields");check(!f.raw.get(Memory::element+0x18,4)&&!f.raw.get(Memory::element+0x20)&&!f.raw.get(Memory::element+0x28)&&f.raw.get(destination+4,4)==0x12345678&&f.raw.get(Memory::element+0x1c,4)==0x76543210,"move clears source fields and preserves both padding cells");}else check(f.lower.frees.empty()&&f.raw.get(Memory::element+0x18,4)==0x201,"null/self output skips ownership transfer");f.check_depth();}
    {Fixture f;f.element(2);f.raw.set(Memory::element+0x18,0x201,4);f.raw.set(Memory::element+0x20,0xf101);f.raw.set(Memory::element+0x28,0xf109);check(f.parse(Memory::input_address,Memory::element+0x20)==Memory::input_address+1&&!f.raw.get(Memory::element+0x20)&&!f.raw.get(Memory::element+0x28)&&f.raw.get(Memory::element+0x30)==0x201,"partially overlapping pair move preserves sequential field load/store semantics");}
    // Four cleanup entry paths all remove an unlinked allocation by swap-last.
    for(unsigned path=0;path<4;++path)for(std::uint32_t count:{0U,1U,3U,0xffffffffU}){Fixture f;if(path==0)f.lower.parse_hook=[](const auto&){return 0;};if(path==1)f.nodes.probe_hook=[](auto t,auto n)->std::uint64_t{return t==Memory::probe48&&n==Memory::child?Memory::declaration:0;};if(path>=2)f.element(path==2?1:2,true);
        const auto original_hook=f.nodes.probe_hook;f.nodes.probe_hook=[&,original_hook](auto t,auto n)->std::uint64_t{if(t==Memory::probe38&&n==Memory::child)return 0;return original_hook?original_hook(t,n):(t==Memory::probe38?1:0);};f.raw.set(Memory::doc+0x104,count,4);f.raw.set(Memory::entries,Memory::child);f.raw.set(Memory::entries+8,0xfb01);f.raw.set(Memory::entries+16,0xfb02);
        (void)f.parse();check(f.raw.get(Memory::doc+0x104,4)==((count>0&&count<0x80000000U)?count-1:count),"each cleanup path respects signed count and decrements positive matched allocation");if(count==3)check(f.raw.get(Memory::entries)==0xfb02,"cleanup swaps cached bounded last entry into matched slot");f.check_destroy();f.check_depth();}
    {Fixture f;f.lower.parse_hook=[](const auto&){return 0;};f.nodes.probe_hook=[](auto,auto){return 0;};f.raw.set(Memory::doc+0xa8,Memory::doc+0x100);f.raw.set(Memory::doc+0x100,Memory::child);(void)f.parse();check(f.raw.get(Memory::doc+0x104,4)==0xffffffffU,"swap store alias changes count before live DWORD decrement");}
}
void failure_prefixes(){
    {Fixture f;f.lower.identify_hook=[](const auto&)->std::uintptr_t{throw Failure{};};fails([&]{(void)f.parse();});check(f.raw.get(Memory::doc+0xa4,4)==1&&!f.raw.get(Memory::scratch_address)&&f.lower.parses.empty(),"Identify failure retains depth and initialized out slot,without synthetic epilog");}
    {Fixture f;f.lower.parse_hook=[](const auto&)->std::uintptr_t{throw Failure{};};fails([&]{(void)f.parse();});check(f.raw.get(Memory::doc+0xa4,4)==1&&f.raw.get(Memory::scratch_address,4)==27&&!f.raw.get(Memory::pair,4)&&f.nodes.destroys.empty(),"child parse failure preserves scratch/line prefix without cleanup");}
    {Fixture f;f.lower.parse_hook=[](const auto&){return 0;};f.nodes.destroy_hook=[](const auto&){throw Failure{};};fails([&]{(void)f.parse();});check(f.raw.get(Memory::doc+0xa4,4)==1&&f.nodes.releases.empty()&&f.lower.errors.empty(),"destructor failure prevents release,diagnostic and normal depth decrement");}
    {Fixture f;f.raw.omitted={{Memory::pair+16,8}};f.raw.refresh();unmapped([&]{(void)f.parse();});check(f.raw.get(Memory::doc+0xa4,4)==1&&!f.raw.get(Memory::pair,4)&&!f.raw.get(Memory::pair+8)&&f.lower.parses.empty(),"missing scratch end mapping retains earlier field stores only");}
    {Fixture f;f.element(1,true);f.lower.error_hook=[](const auto&){throw Failure{};};fails([&]{(void)f.parse();});check(f.raw.get(Memory::doc+0xa4,4)==1&&f.nodes.destroys.empty()&&f.lower.frees.empty(),"error transport failure does not invent child cleanup or unwind");}
}
}
int main(){try{entry_depth_and_scratch();append_backedge_and_failed_parse();declarations();matching_and_mismatching_elements();closing_move_and_cleanup();failure_prefixes();std::cout<<"PASS: "<<checks<<" node-parse core checks; depth/scratch/live documents,declaration/mode branches,explicit pointer errors,append/move aliases,four cleanup paths and failure prefixes; lower primitives/DOM/nativeABI supplied/open\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL after "<<checks<<" checks\n";return 1;}}
